import java.util.Scanner;
public class FahrenheitToCelsius {
	public static void main(String[] args) {
		//Paso 1: Definir los datos que necesitamos para este programa
		final int BASE = 32;
		final double CONVERSION_FACTOR = 5.0 / 9;
		//Paso 2: Leer el valor Fahrenheit de entrada
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese el valor en Fahrenheit: ");
		int fahrenheitTemp = scan.nextInt();
		scan.close();
		//Paso 3: Calcular el equivalente en Celsius del valor Fahrenheit
		double celsiusTemp = (fahrenheitTemp - BASE) * CONVERSION_FACTOR ;
		System.out.println("Temperatura en Fahrenheit: " + fahrenheitTemp);
		System.out.println("Equivalente en Celsius: " + celsiusTemp);
	}
}

